package draftui

import (
	"encoding/json"
	"os"
	"strings"
	"testing"
)

// TestHighlightMatchesRust checks the Go tokenizer against the golden fixtures generated by the
// Rust tokenizer (tests/fixtures/highlight.json). If it fails, the two implementations disagree:
// fix the Go port (Rust is the source of truth) or, after changing the Rust tokenizer on purpose,
// regenerate with `UPDATE_GOLDEN=1 cargo test --test highlight_golden`.
func TestHighlightMatchesRust(t *testing.T) {
	raw, err := os.ReadFile("tests/fixtures/highlight.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct {
		Lang   string      `json:"lang"`
		Input  string      `json:"input"`
		Tokens [][2]string `json:"tokens"`
	}
	if err := json.Unmarshal(raw, &cases); err != nil {
		t.Fatal(err)
	}
	if len(cases) == 0 {
		t.Fatal("no golden cases")
	}
	for i, c := range cases {
		got := Tokens(c.Lang, c.Input)
		var gotPairs [][2]string
		for _, s := range got {
			gotPairs = append(gotPairs, [2]string{s.Class, s.Text})
		}
		if len(gotPairs) != len(c.Tokens) {
			t.Errorf("case %d (%s %q): %d tokens, want %d\n got:  %v\n want: %v", i, c.Lang, c.Input, len(gotPairs), len(c.Tokens), gotPairs, c.Tokens)
			continue
		}
		for j := range gotPairs {
			if gotPairs[j] != c.Tokens[j] {
				t.Errorf("case %d (%s %q) token %d: got %v want %v", i, c.Lang, c.Input, j, gotPairs[j], c.Tokens[j])
			}
		}
	}
}

func TestHighlightEscapesHTML(t *testing.T) {
	got := string(Highlight("json", `{"a": "<script>alert(1)</script>"}`))
	if strings.Contains(got, "<script>") {
		t.Fatalf("unescaped markup: %s", got)
	}
	if !strings.Contains(got, `<span class="tk-key">`) {
		t.Fatalf("no key span: %s", got)
	}
}

func TestHighlightRoundTripsText(t *testing.T) {
	src := "steps:\n  - name: a\n    uses: builtin://sleep\n    with: { for: 5s }  # wait"
	var b strings.Builder
	for _, s := range Tokens("yaml", src) {
		b.WriteString(s.Text)
	}
	if b.String() != src {
		t.Fatalf("lost text: %q", b.String())
	}
}
